{
  "implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    segments = case.get('segments')
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('segments must be a non-empty list')
    budget = case.get('budget')
    if not isinstance(budget, (int, float)) or budget != int(budget):
        raise ValueError('budget must be an integer')
    budget = int(budget)

    names = []
    min_vals = []
    caps = []
    imps = []
    for i, seg in enumerate(segments):
        if not isinstance(seg, dict):
            raise ValueError(f'segment {i} must be a dict')
        name = seg.get('name')
        importance = seg.get('importance')
        minimum = seg.get('minimum')
        capacity = seg.get('capacity')
        if not all(isinstance(x, (int, float)) for x in (importance, minimum, capacity)):
            raise ValueError(f'segment {i} fields must be numeric')
        names.append(str(name))
        imps.append(int(importance))
        min_vals.append(int(minimum))
        caps.append(int(capacity))

    sum_min = sum(min_vals)
    sum_cap = sum(caps)
    if budget < sum_min or budget > sum_cap:
        raise ValueError(f'budget {budget} not between {sum_min} and {sum_cap}')

    allocations = min_vals[:]
    remaining = budget - sum_min

    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i in range(len(segments)):
            if allocations[i] < caps[i]:
                score = imps[i] / (allocations[i] + 1.0)
                if score > best_score:
                    best_score = score
                    best_idx = i
                elif score == best_score and best_idx == -1:
                    best_idx = i
        if best_idx == -1:
            # should not happen because remaining <= sum of spare capacity
            break
        allocations[best_idx] += 1
        remaining -= 1

    by_name = {names[i]: allocations[i] for i in range(len(segments))}
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': budget
    }"
}
